public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = Set.copyOf(statuses);
    }

    /**
     * Whether {@code customer} passes this filter.
     *
     * <p>The name text is split on whitespace into terms, and each term must appear,
     * ignoring case and accents, in the first name or the last name.
     */
    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }
        List<String> terms = nameTerms();
        if (terms.isEmpty()) {
            return true;
        }
        String firstName = fold(customer.firstName());
        String lastName = fold(customer.lastName());
        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
    }

    private List<String> nameTerms() {
        return Arrays.stream(name.strip().split("\\s+"))
                .filter(term -> !term.isEmpty())
                .map(CustomerFilter::fold)
                .toList();
    }

    /** Lower-cases {@code text} and strips accents, so that "Mäkinen" folds to "makinen". */
    private static String fold(String text) {
        return Normalizer.normalize(text, Normalizer.Form.NFD)
                .replaceAll("\\p{M}+", "")
                .toLowerCase(Locale.ROOT);
    }
